NOT_COVERED, COVERED_NO_CAM, HAS_CAM = 0, 1, 2

def min_camera_cover(root):
    cameras = 0
    def dfs(node):
        nonlocal cameras
        if node is None:
            return COVERED_NO_CAM                            # null needs no coverage
        left = dfs(node.left)
        right = dfs(node.right)
        if left == NOT_COVERED or right == NOT_COVERED:
            cameras += 1                                        # FORCED: a child is uncovered
            return HAS_CAM
        if left == HAS_CAM or right == HAS_CAM:
            return COVERED_NO_CAM                                # covered by a child's camera
        return NOT_COVERED                                       # defer the decision upward
    if dfs(root) == NOT_COVERED:
        cameras += 1                                             # root itself needs a camera
    return cameras

