const int NOT_COVERED = 0, COVERED_NO_CAM = 1, HAS_CAM = 2;
int cameras;

int dfs(TreeNode* node) {
    if (!node) return COVERED_NO_CAM;                                 // null needs no coverage
    int left = dfs(node->left);
    int right = dfs(node->right);
    if (left == NOT_COVERED || right == NOT_COVERED) {
        cameras++;                                                       // FORCED: a child is uncovered
        return HAS_CAM;
    }
    if (left == HAS_CAM || right == HAS_CAM) return COVERED_NO_CAM;     // covered by a child's camera
    return NOT_COVERED;                                                 // defer the decision upward
}

int minCameraCover(TreeNode* root) {
    cameras = 0;
    if (dfs(root) == NOT_COVERED) cameras++;                            // root itself needs a camera
    return cameras;
}
